module proj8_top(SCLK, MOSI, CSN, rst_n, clk_mem, MISO, MISO_enable);
  input SCLK, MOSI, CSN, rst_n, clk_mem;
  output MISO, MISO_enable;
  wire SCLK, MOSI, CSN, rst_n, clk_mem;
  wire MISO, MISO_enable;
  wire [5:0] spi_addr;
  wire [7:0] spi_write_data;
  wire [7:0] mem_read_data;
  wire [7:0] spi_read_data;
  wire [5:0] mem_addr;
  wire [7:0] mem_write_data;
  wire mem_done, mem_start, mem_write, rst_n_mem, rst_n_spi,
       spi_read_req, spi_write_req;
  spi_mem_cdc cdc(.SCLK (SCLK), .clk_mem (clk_mem), .rst_n_spi
       (rst_n_spi), .rst_n_mem (rst_n_mem), .spi_addr (spi_addr),
       .spi_write_data (spi_write_data), .spi_write_req
       (spi_write_req), .spi_read_req (spi_read_req), .spi_read_data
       (spi_read_data), .mem_start (mem_start), .mem_write (mem_write),
       .mem_addr (mem_addr), .mem_write_data (mem_write_data),
       .mem_done (mem_done), .mem_read_data (mem_read_data));
  memory_controller mem_ctrl(.clk_mem (clk_mem), .rst_n_mem
       (rst_n_mem), .start (mem_start), .write_req (mem_write), .addr
       (mem_addr), .write_data (mem_write_data), .done (mem_done),
       .read_data (mem_read_data));
  reset_sequencer reset_control(.rst_n (rst_n), .SCLK (SCLK), .clk_mem
       (clk_mem), .rst_n_spi (rst_n_spi), .rst_n_mem (rst_n_mem));
  SPI_interface spi(.SCLK (SCLK), .MOSI (MOSI), .CSN (CSN), .rst_n
       (rst_n_spi), .MISO (MISO), .MISO_enable (MISO_enable), .mem_addr
       (spi_addr), .mem_write_data (spi_write_data), .mem_write_req
       (spi_write_req), .mem_read_req (spi_read_req), .mem_read_data
       (spi_read_data));
endmodule

